{
 "summary": "The first target proves that there is a finite, connected, bipartite, 2-degenerate graph H on Fin q with ex(n,H) ≥ c·n^{3/2+ε} for all sufficiently large n, for some constants c, ε > 0. It also proves an extra property not in the paper: under every proper 2-colouring, each colour class contains a vertex of degree > 2. The second target proves the negation of a formalized Erdős degeneracy conjecture: for every r > 0 and every finite bipartite r-degenerate H, ex(n,H) = O(n^{2−1/r}). Both statements match the paper; the only deviation is the harmless extra colouring/degree conjunct, which makes Lean stronger.",
 "glossary": [
  {"decl": "neighborsWithin", "line": 8, "plain": "For a finite set s and vertex v: the set of vertices in s adjacent to v in G.", "standard_concept": "neighbourhood of v restricted to s", "matches_standard": "yes", "note": ""},
  {"decl": "IsDegenerate", "line": 13, "plain": "Every nonempty finite vertex set s contains a vertex with at most r neighbours inside s.", "standard_concept": "r-degenerate graph", "matches_standard": "yes", "note": "Stated for induced subgraphs. This is equivalent to the paper's 'every nonempty subgraph has a vertex of degree ≤ r', since deleting edges only lowers degrees."},
  {"decl": "IsTwoDegenerate", "line": 17, "plain": "IsDegenerate 2 G", "standard_concept": "2-degenerate graph", "matches_standard": "yes", "note": ""},
  {"decl": "DegeneracyConjectureStatement", "line": 20, "plain": "For all r > 0 and all bipartite r-degenerate graphs H on Fin q, ex(n,H) = O(n^{2−1/r}) as n → ∞.", "standard_concept": "Erdős degeneracy conjecture (3)", "matches_standard": "yes", "note": "Uses Mathlib's extremalNumber, which matches the paper's ex(n,H). The hypothesis r > 0 avoids the 1/0 junk value."}
 ],
 "lean_claims": [
  {"theorem": "twoDegenerateExtremalCounterexample", "line": 28, "plain": "There exist q and a graph H on Fin q with all of the following: H is connected, bipartite and 2-degenerate; for every proper 2-colouring and each colour class, the maximum degree over that class exceeds 2; and there are reals c > 0, ε > 0 with c·n^{3/2+ε} ≤ ex(n,H) for all sufficiently large n."},
  {"theorem": "not_erdos_146", "line": 43, "plain": "There exist r > 0 and a bipartite r-degenerate graph H on Fin q such that ex(n,H) is not O(n^{2−1/r})."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.2", "plain": "There exist a fixed connected bipartite 2-degenerate graph H and constants c, ε > 0 with ex(n,H) ≥ c·n^{3/2+ε} for all sufficiently large n."},
  {"ref": "Abstract / §1.2", "plain": "Erdős's conjecture that every bipartite r-degenerate graph has ex(n,H) = O(n^{2−1/r}) is false (already for r = 2)."},
  {"ref": "Theorem 1.1", "plain": "Failure of compactness (covered elsewhere, sibling file)."}
 ],
